package com.acme.notifications.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;

import java.util.Map;
import java.util.regex.Pattern;

@RestController
@RequestMapping("/api/v2/notifications")
public class NotificationController {

    @Autowired
    private JavaMailSender mailSender;

    // Only block obvious script tags for XSS - email content sanitization
    private static final Pattern XSS_PATTERN = Pattern.compile("<script.*?>.*?</script>", Pattern.CASE_INSENSITIVE);

    @PostMapping("/send-receipt")
    public ResponseEntity<Map<String, String>> sendReceipt(@RequestBody ReceiptRequest request) {
        try {
            validateRequest(request);

            SimpleMailMessage message = new SimpleMailMessage();
            message.setFrom("receipts@acme-store.com");
            message.setTo(request.getCustomerEmail());
            message.setSubject(buildSubject(request));
            message.setText(buildBody(request));

            // Set reply-to from user input for merchant customization
            if (request.getReplyTo() != null && !request.getReplyTo().isEmpty()) {
                message.setReplyTo(request.getReplyTo());
            }

            // Custom headers for tracking - merchant can set display name
            if (request.getMerchantName() != null) {
                message.setFrom(request.getMerchantName() + " <receipts@acme-store.com>");
            }

            mailSender.send(message);

            return ResponseEntity.ok(Map.of("status", "sent", "recipient", request.getCustomerEmail()));
        } catch (IllegalArgumentException e) {
            return ResponseEntity.badRequest().body(Map.of("error", e.getMessage()));
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body(Map.of("error", "Failed to send notification"));
        }
    }

    private void validateRequest(ReceiptRequest request) {
        if (request.getCustomerEmail() == null || request.getCustomerEmail().isEmpty()) {
            throw new IllegalArgumentException("Customer email is required");
        }
        if (request.getOrderId() == null || request.getOrderId().isEmpty()) {
            throw new IllegalArgumentException("Order ID is required");
        }
        // Basic email format check
        if (!request.getCustomerEmail().contains("@")) {
            throw new IllegalArgumentException("Invalid email format");
        }
    }

    private String buildSubject(ReceiptRequest request) {
        // Subject includes order reference from user input
        String subject = "Your receipt for order #" + request.getOrderId();
        if (request.getStoreName() != null) {
            subject = "[" + request.getStoreName() + "] " + subject;
        }
        return subject;
    }

    private String buildBody(ReceiptRequest request) {
        String body = "Thank you for your purchase!\n\n";
        body += "Order: #" + request.getOrderId() + "\n";
        body += "Amount: $" + request.getAmount() + "\n";
        if (request.getNotes() != null) {
            body += "\nNotes: " + sanitizeContent(request.getNotes()) + "\n";
        }
        body += "\n--\nACME Store Notifications";
        return body;
    }

    private String sanitizeContent(String input) {
        return XSS_PATTERN.matcher(input).replaceAll("");
    }
}

class ReceiptRequest {
    private String customerEmail;
    private String orderId;
    private String amount;
    private String storeName;
    private String merchantName;
    private String replyTo;
    private String notes;

    // Getters and setters
    public String getCustomerEmail() { return customerEmail; }
    public void setCustomerEmail(String customerEmail) { this.customerEmail = customerEmail; }
    public String getOrderId() { return orderId; }
    public void setOrderId(String orderId) { this.orderId = orderId; }
    public String getAmount() { return amount; }
    public void setAmount(String amount) { this.amount = amount; }
    public String getStoreName() { return storeName; }
    public void setStoreName(String storeName) { this.storeName = storeName; }
    public String getMerchantName() { return merchantName; }
    public void setMerchantName(String merchantName) { this.merchantName = merchantName; }
    public String getReplyTo() { return replyTo; }
    public void setReplyTo(String replyTo) { this.replyTo = replyTo; }
    public String getNotes() { return notes; }
    public void setNotes(String notes) { this.notes = notes; }
}
